package org.acme.wiki;

public class Export {
    public byte[] render(String page) {
        return page.getBytes(java.nio.charset.StandardCharsets.UTF_8);
    }
}

package org.acme.wiki;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class ExportTest {
    @Test
    void writesUtf8Pages() {
        assertArrayEquals("\u00e9".getBytes(java.nio.charset.StandardCharsets.UTF_8), new Export().render("\u00e9"));
    }
}

